30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /** Disposable email domains that are not accepted as an owner's email. */
108	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
109	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
110	
111	    /**
112	     * Normalize the optional email: absent stays absent; when present it must be syntactically
113	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
114	     * domain is on the disposable-domain blocklist.
115	     */
116	    private boolean normalizeEmail(Owner owner) {
117	        String email = owner.getEmail();
118	        if (email == null || email.isEmpty()) {
119	            owner.setEmail(null);
120	            return true;
121	        }
122	        if (!EMAIL_PATTERN.matcher(email).matches()) {
123	            return false;
124	        }
125	        email = email.toLowerCase(java.util.Locale.ROOT);
126	        String domain = email.substring(email.indexOf('@') + 1);
127	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
128	            return false;
129	        }
130	        owner.setEmail(email);
131	        return true;
132	    }
133	
134	    /**
135	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
136	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
137	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
138	     *
139	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
140	     *         a valid E.164 number.
141	     */
142	    private static String toE164(String raw) {
143	        if (raw == null) {
144	            return null;
145	        }
146	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
147	        String digits;
148	        if (cleaned.startsWith("+")) {
149	            digits = cleaned.substring(1);
150	        } else {
151	            if (cleaned.startsWith("0")) {
152	                cleaned = cleaned.substring(1);
153	            }
154	            digits = "61" + cleaned;
155	        }
156	        if (!digits.matches("\\d{8,15}")) {
157	            return null;
158	        }
159	        return "+" + digits;
160	    }
161	
162	    /**
163	     * Validate the national-number length of a canonical E.164 string against its country code:
164	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
165	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
166	     * string produced by {@link #toE164}.
167	     *
168	     * @return {@code true} when the national-number length is correct for the country code.
169	     */
170	    private static boolean hasValidNationalLength(String e164) {
171	        String digits = e164.substring(1);
172	        if (digits.startsWith("61")) {
173	            return digits.length() - 2 == 9;
174	        }
175	        if (digits.startsWith("1")) {
176	            return digits.length() - 1 == 10;
177	        }
178	        return true;
179	    }
180	
181	    /**
182	     * Build the customer code {@code <REGION>-<HASH8>}: REGION is the region code derived from the
183	     * owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no known
184	     * range) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the concatenation of
185	     * the owner's normalized (E.164) telephone and last name (e.g. {@code NSW-3F9A0C17}). No sequence
186	     * numbers are used, so the base code is a pure function of the owner's region-and-hash identity.
187	     * When that base code collides with an existing owner's customerCode, {@code -<n>} is appended with
188	     * the smallest {@code n} of 2 or more that makes it unique, returning the de-duplicated code.
189	     */
190	    private String customerCodeFor(Owner owner) {
191	        String region = ownerMapper.regionFromPostcode(owner);
192	        if (region == null) {
193	            region = "UNKNOWN";
194	        }
195	        String base = region + "-" + hash8(owner.getTelephone(), owner.getLastName());
196	
197	        java.util.Set<String> existingCodes = new java.util.HashSet<>();
198	        for (Owner existing : this.clinicService.findAllOwners()) {
199	            String code = existing.getCustomerCode();
200	            if (code != null) {
201	                existingCodes.add(code);
202	            }
203	        }
204	        if (!existingCodes.contains(base)) {
205	            return base;
206	        }
207	        for (int n = 2; ; n++) {
208	            String candidate = base + "-" + n;
209	            if (!existingCodes.contains(candidate)) {
210	                return candidate;
211	            }
212	        }
213	    }
214	
215	    /**
216	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
217	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
218	     */
219	    private static String hash8(String normalizedTelephone, String lastName) {
220	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
221	            + (lastName == null ? "" : lastName);
222	        try {
223	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
224	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
225	            StringBuilder sb = new StringBuilder(8);
226	            for (int i = 0; i < 4; i++) {
227	                sb.append(String.format("%02X", digest[i]));
228	            }
229	            return sb.toString();
230	        }
231	        catch (java.security.NoSuchAlgorithmException e) {
232	            throw new IllegalStateException(e);
233	        }
234	    }
235	
236	    /** Common street-type abbreviations expanded during address normalization. */
237	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
238	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
239	
240	    /**
241	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
242	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
243	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
244	     */
245	    private static String normalizeAddress(String value) {
246	        if (value == null) {
247	            return "";
248	        }
249	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
250	        if (collapsed.isEmpty()) {
251	            return "";
252	        }
253	        String[] tokens = collapsed.split(" ");
254	        StringBuilder sb = new StringBuilder(collapsed.length());
255	        for (int i = 0; i < tokens.length; i++) {
256	            if (i > 0) {
257	                sb.append(' ');
258	            }
259	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
260	        }
261	        return sb.toString();
262	    }
263	
264	    /**
265	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
266	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
267	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
268	     */
269	    private static String normalizeForHousehold(String value) {
270	        if (value == null) {
271	            return "";
272	        }
273	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
274	    }
275	
276	    /**
277	     * Return the owners that already share this owner's household, i.e. resolve to the same
278	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
279	     * postcode).
280	     */
281	    private List<Owner> householdMembers(Owner owner) {
282	        String householdId = householdIdFor(owner);
283	        List<Owner> members = new java.util.ArrayList<>();
284	        for (Owner existing : this.clinicService.findAllOwners()) {
285	            if (householdId.equals(householdIdFor(existing))) {
286	                members.add(existing);
287	            }
288	        }
289	        return members;
290	    }
291	
292	    /**
293	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
294	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
295	     */
296	    private boolean sharesHouseholdWithExisting(Owner owner) {
297	        return !householdMembers(owner).isEmpty();
298	    }
299	
300	    /**
301	     * Count the existing owners that share this owner's first name and last name, compared
302	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
303	     */
304	    private int namesakeCount(Owner owner) {
305	        String firstName = owner.getFirstName();
306	        String lastName = owner.getLastName();
307	        int count = 0;
308	        for (Owner existing : this.clinicService.findAllOwners()) {
309	            if (firstName != null && lastName != null
310	                && firstName.equalsIgnoreCase(existing.getFirstName())
311	                && lastName.equalsIgnoreCase(existing.getLastName())) {
312	                count++;
313	            }
314	        }
315	        return count;
316	    }
317	
318	    /**
319	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
320	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
321	     * Because it is a pure function of the last name and postcode, every owner in the same household
322	     * deterministically resolves to the same value.
323	     */
324	    private static String householdIdFor(Owner owner) {
325	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
326	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
327	        try {
328	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
329	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
330	            StringBuilder sb = new StringBuilder(12);
331	            for (int i = 0; i < 6; i++) {
332	                sb.append(String.format("%02X", digest[i]));
333	            }
334	            return sb.toString();
335	        }
336	        catch (java.security.NoSuchAlgorithmException e) {
337	            throw new IllegalStateException(e);
338	        }
339	    }
340	
341	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
342	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
343	        "NSW", new int[] {2000, 2099},
344	        "VIC", new int[] {3000, 3099},
345	        "QLD", new int[] {4000, 4099});
346	
347	    /**
348	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
349	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
350	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
351	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
352	     * postcode.
353	     */
354	    private boolean isPostcodeValid(Owner owner) {
355	        String postcode = owner.getPostcode();
356	        if (postcode == null || postcode.isEmpty()) {
357	            return true;
358	        }
359	        if (!postcode.matches("\\d{4}")) {
360	            return false;
361	        }
362	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
363	        if (range == null) {
364	            return true;
365	        }
366	        int value = Integer.parseInt(postcode);
367	        return value >= range[0] && value <= range[1];
368	    }
369	
370	    /**
371	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
372	     * "possible duplicate": one that shares the owner's last name (case-insensitive) and postcode
373	     * but carries a different (normalized) telephone. When several match, the one with the smallest
374	     * id is chosen so the result is deterministic. Returns {@code null} when the owner has no
375	     * postcode or no such existing owner exists.
376	     */
377	    private Owner possibleDuplicateOf(Owner owner) {
378	        String lastName = owner.getLastName();
379	        String postcode = owner.getPostcode();
380	        String telephone = owner.getTelephone();
381	        if (lastName == null || postcode == null || postcode.isEmpty()) {
382	            return null;
383	        }
384	        Owner match = null;
385	        for (Owner existing : this.clinicService.findAllOwners()) {
386	            if (lastName.equalsIgnoreCase(existing.getLastName())
387	                && postcode.equals(existing.getPostcode())
388	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
389	                if (match == null || (existing.getId() != null && match.getId() != null
390	                    && existing.getId() < match.getId())) {
391	                    match = existing;
392	                }
393	            }
394	        }
395	        return match;
396	    }
397	
398	    /** Maximum number of owners permitted in a single city. */
399	    private static final int CITY_CAPACITY = 50;
400	
401	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
402	    private static final int DAILY_CREATE_LIMIT = 100;
403	
404	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
405	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
406	
407	    /**
408	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
409	     * Used to enforce the per-city capacity on create (before this owner is saved).
410	     */
411	    private int cityOwnerCount(Owner owner) {
412	        String city = owner.getCity();
413	        int count = 0;
414	        for (Owner existing : this.clinicService.findAllOwners()) {
415	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
416	                count++;
417	            }
418	        }
419	        return count;
420	    }
421	
422	    /**
423	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
424	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
425	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
426	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
427	     */
428	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
429	        switch (date.getDayOfWeek()) {
430	            case SATURDAY:
431	                return date.plusDays(2);
432	            case SUNDAY:
433	                return date.plusDays(1);
434	            default:
435	                return date;
436	        }
437	    }
438	
439	    /**
440	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
441	     * per-day create limit on create (before this owner is saved).
442	     */
443	    private int ownersRegisteredOn(java.time.LocalDate day) {
444	        int count = 0;
445	        for (Owner existing : this.clinicService.findAllOwners()) {
446	            if (day.equals(existing.getRegistrationDate())) {
447	                count++;
448	            }
449	        }
450	        return count;
451	    }
452	
453	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
454	    @Override
455	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
456	        HttpHeaders headers = new HttpHeaders();
457	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
458	        if (!isPostcodeValid(owner)) {
459	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
460	        }
461	        String telephone = toE164(owner.getTelephone());
462	        if (telephone == null || !hasValidNationalLength(telephone)) {
463	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
464	        }
465	        if (!normalizeEmail(owner)) {
466	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
467	        }
468	        String address = normalizeAddress(owner.getAddress());
469	        if (address.isEmpty()) {
470	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
471	        }
472	        owner.setAddress(address);
473	        owner.setTelephone(telephone);
474	        if (owner.getRegistrationDate() != null
475	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
476	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
477	        }
478	        java.time.LocalDate registrationDate = toBusinessDay(
479	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
480	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
481	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
482	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
483	        }
484	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
485	            return new ResponseEntity<>(HttpStatus.CONFLICT);
486	        }
487	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
488	        // owners with the same last name and postcode automatically share it. The link is no longer
489	        // created by copying an existing owner's id around.
490	        owner.setHouseholdId(householdIdFor(owner));
491	        List<Owner> householdMembers = householdMembers(owner);
492	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
493	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
494	
495	        // Hard duplicate: a new owner whose WHOLE identityKey (telephone|email|householdId) equals an
496	        // existing owner's is a byte-for-byte identity match and is always rejected.
497	        String identityKey = owner.getIdentityKey();
498	        for (Owner existing : this.clinicService.findAllOwners()) {
499	            if (identityKey.equals(existing.getIdentityKey())) {
500	                return new ResponseEntity<>(HttpStatus.CONFLICT);
501	            }
502	        }
503	        // Household duplicate: another owner already shares this (last name, postcode) household.
504	        // Rejected as a duplicate unless the caller sets 'sharesHousehold', which now only bypasses
505	        // this block (the shared householdId itself is already assigned deterministically above).
506	        if (!householdMembers.isEmpty() && !sharesHousehold) {
507	            return new ResponseEntity<>(HttpStatus.CONFLICT);
508	        }
509	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner that
510	        // shares an existing owner's last name and postcode with a different telephone.
511	        if (declaredHouseholdMember) {
512	            owner.setPossibleDuplicate(false);
513	            owner.setPossibleDuplicateOf(null);
514	        }
515	        else {
516	            Owner duplicateOf = possibleDuplicateOf(owner);
517	            owner.setPossibleDuplicate(duplicateOf != null);
518	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
519	        }
520	        owner.setNamesakeCount(namesakeCount(owner));
521	        owner.setHouseholdSize(householdMembers.size() + 1);
522	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
523	        owner.setRegistrationDate(registrationDate);
524	        owner.setCustomerCode(customerCodeFor(owner));
525	        this.clinicService.saveOwner(owner);
526	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
527	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
528	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
529	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
530	        headers.setLocation(UriComponentsBuilder.newInstance()
531	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
532	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
533	    }
534	
535	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
536	    @Override
537	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
538	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
539	        if (currentOwner == null) {
540	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
541	        }
542	        currentOwner.setAddress(ownerFieldsDto.getAddress());
543	        currentOwner.setCity(ownerFieldsDto.getCity());
544	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
545	        currentOwner.setLastName(ownerFieldsDto.getLastName());
546	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
547	        currentOwner.setEmail(ownerFieldsDto.getEmail());
548	        if (!normalizeEmail(currentOwner)) {
549	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
550	        }
551	        this.clinicService.saveOwner(currentOwner);
552	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
553	    }
554	
555	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
556	    @Transactional
557	    @Override
558	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
559	        Owner owner = this.clinicService.findOwnerById(ownerId);
560	        if (owner == null) {
561	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
562	        }
563	        this.clinicService.deleteOwner(owner);
564	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Override
569	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
570	        Owner owner = this.clinicService.findOwnerById(ownerId);
571	        if (owner == null) {
572	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
573	        }
574	        HttpHeaders headers = new HttpHeaders();
575	        Pet pet = petMapper.toPet(petFieldsDto);
576	        owner.setId(ownerId);
577	        pet.setOwner(owner);
578	        pet.getType().setName(null);
579	        this.clinicService.savePet(pet);
580	        PetDto petDto = petMapper.toPetDto(pet);
581	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
582	            .buildAndExpand(pet.getId()).toUri());
583	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
584	    }
585	
586	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
587	    @Override
588	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
589	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
590	        if (currentOwner != null) {
591	            Pet currentPet = this.clinicService.findPetById(petId);
592	            if (currentPet != null) {
593	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
594	                currentPet.setName(petFieldsDto.getName());
595	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
596	                this.clinicService.savePet(currentPet);
597	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
598	            }
599	        }
600	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
601	    }
602	
603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
606	        HttpHeaders headers = new HttpHeaders();
607	        Visit visit = visitMapper.toVisit(visitFieldsDto);
608	        Pet pet = new Pet();
609	        pet.setId(petId);
610	        visit.setPet(pet);
611	        this.clinicService.saveVisit(visit);
612	        VisitDto visitDto = visitMapper.toVisitDto(visit);
613	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
614	            .buildAndExpand(visit.getId()).toUri());
615	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
616	    }
617	
618	
619	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
620	    @Override
621	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
622	        Owner owner = this.clinicService.findOwnerById(ownerId);
623	        if (owner != null) {
624	            Pet pet = owner.getPet(petId);
625	            if (pet != null) {
626	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
627	            }
628	        }
629	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
630	    }
631	}
