18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
25	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
31	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * Formats the stored E.164 {@code telephone} for humans: the {@code '+'} and country code, a
36	     * space, then the national digits grouped in threes (e.g. {@code +61412345678} -&gt;
37	     * {@code +61 412 345 678}). The country code is taken as {@code 61} (Australia) or {@code 1}
38	     * (NANP) when recognised, otherwise a single leading digit. Returns {@code null} when the
39	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164
40	     * number.
41	     */
42	    default String telephoneDisplay(Owner owner) {
43	        String telephone = owner.getTelephone();
44	        if (telephone == null || telephone.isEmpty()) {
45	            return null;
46	        }
47	        if (!telephone.startsWith("+") || !telephone.substring(1).matches("\\d+")) {
48	            return telephone;
49	        }
50	        String digits = telephone.substring(1);
51	        int countryCodeLength;
52	        if (digits.startsWith("61")) {
53	            countryCodeLength = 2;
54	        }
55	        else if (digits.startsWith("1")) {
56	            countryCodeLength = 1;
57	        }
58	        else {
59	            countryCodeLength = 1;
60	        }
61	        String countryCode = digits.substring(0, countryCodeLength);
62	        String national = digits.substring(countryCodeLength);
63	        StringBuilder grouped = new StringBuilder();
64	        for (int i = 0; i < national.length(); i++) {
65	            if (i > 0 && i % 3 == 0) {
66	                grouped.append(' ');
67	            }
68	            grouped.append(national.charAt(i));
69	        }
70	        return "+" + countryCode + (national.isEmpty() ? "" : " " + grouped);
71	    }
72	
73	    /**
74	     * Derives the owner's age band from {@code birthDate} measured against {@code registrationDate}:
75	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older.
76	     * Returns {@code null} when no birthDate is recorded. When the registrationDate is absent (e.g.
77	     * legacy records) the current date is used as the reference point.
78	     */
79	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
80	        java.time.LocalDate birthDate = owner.getBirthDate();
81	        if (birthDate == null) {
82	            return null;
83	        }
84	        java.time.LocalDate reference = owner.getRegistrationDate() != null
85	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
86	        int age = java.time.Period.between(birthDate, reference).getYears();
87	        if (age < 18) {
88	            return OwnerDto.AgeBandEnum.MINOR;
89	        }
90	        if (age < 65) {
91	            return OwnerDto.AgeBandEnum.ADULT;
92	        }
